async recoverUnconfirmed(id: string) {
  const snapshot = await this.db.asaasPayout.findUnique({ where: { withdrawalId: id } });
  if (!snapshot || snapshot.environment !== 'sandbox' || snapshot.transferId ||
      !['UNKNOWN', 'SENDING'].includes(snapshot.state)) return;
  if (Date.now() - new Date(snapshot.updatedAt).getTime() < 120000) return;
  let offset = 0;
  let complete = false;
  const matches = new Map<string, any>();
  for (let page = 0; page < 20; page++) {
    const result = await this.api('/transfers?limit=100&offset=' + offset);
    if (!Array.isArray(result?.data) || typeof result.hasMore !== 'boolean') {
      throw new ConflictException('Consulta Asaas incompleta. Saldo preservado.');
    }
    for (const transfer of result.data) {
      if (transfer.externalReference === 'porto-withdrawal:' + id ||
          transfer.description === 'Saque Porto Prime ' + id) {
        if (!transfer.id) throw new ConflictException('Transferencia sem identificador.');
        matches.set(transfer.id, transfer);
      }
    }
    if (!result.hasMore) { complete = true; break; }
    if (!result.data.length) throw new ConflictException('Paginacao Asaas incompleta.');
    offset += result.data.length;
  }
  if (!complete || matches.size > 1) throw new ConflictException('Conciliacao inconclusiva. Saldo preservado.');
  if (matches.size === 1) {
    const transfer = [...matches.values()][0];
    // Read canonical provider data and preserve all existing identity/value checks.
    const canonical = await this.api('/transfers/' + encodeURIComponent(transfer.id));
    await this.apply(canonical, id);
    return;
  }
  // Only a documented HTTP 409 rejection plus a complete absence check can
  // close this legacy stuck state. Timeouts and 5xx never imply failure.
  if (snapshot.providerStatus || !String(snapshot.lastError ?? '').includes('(ASAAS_HTTP_409)')) return;
  const courierId = await this.db.$transaction(async (tx: any) => {
    await tx.$queryRawUnsafe('SELECT "id" FROM "Withdrawal" WHERE "id" = $1 FOR UPDATE', id);
    const current = await tx.asaasPayout.findUnique({ where: { withdrawalId: id } });
    if (!current || current.state !== snapshot.state || current.transferId ||
        current.environment !== 'sandbox' || current.providerStatus || current.lastError !== snapshot.lastError ||
        new Date(current.updatedAt).getTime() !== new Date(snapshot.updatedAt).getTime()) return null;
    const withdrawal = await tx.withdrawal.findUniqueOrThrow({ where: { id } });
    if (withdrawal.status !== 'PROCESSING') return null;
    const reservation = await tx.courierLedgerEntry.findUnique({
      where: { idempotencyKey: 'withdrawal:' + id + ':reserve' },
    });
    const reversed = await tx.courierLedgerEntry.findUnique({
      where: { idempotencyKey: 'withdrawal:' + id + ':reversal' },
    });
    if (!reservation || reservation.courierId !== withdrawal.courierId ||
        reservation.type !== 'WITHDRAWAL_DEBIT' || !(Number(withdrawal.amount) > 0) ||
        Number(reservation.amount) !== -Number(withdrawal.amount) || reversed) {
      throw new ConflictException('Reserva divergente. Conciliacao manual necessaria.');
    }
    await tx.courierLedgerEntry.create({ data: {
      courierId: withdrawal.courierId, type: 'REVERSAL', amount: withdrawal.amount,
      description: 'Saldo devolvido: saque recusado por repeticao recente',
      idempotencyKey: 'withdrawal:' + id + ':reversal',
      metadata: { withdrawalId: id, provider: 'ASAAS', reason: 'HTTP_409_RECONCILED',
        reconciledAt: new Date().toISOString() },
    } });
    await tx.withdrawal.update({ where: { id }, data: { status: 'REJECTED', processedAt: new Date() } });
    await tx.asaasPayout.update({ where: { withdrawalId: id }, data: {
      state: 'FAILED', providerStatus: 'REQUEST_REJECTED',
      lastError: 'ASAAS_HTTP_409: tentativa recusada por repeticao recente. Nenhuma transferencia vinculada encontrada; saldo devolvido. Aguarde o intervalo antes de solicitar novamente.',
    } });
    return withdrawal.courierId;
  });
  if (courierId) {
    await this.notify(courierId);
    this.logger.log('Saque com HTTP 409 conciliado: solicitacao encerrada e saldo devolvido.');
  }

// Recover requests whose provider ID was never saved, without another POST.
const unconfirmed = await this.db.asaasPayout.findMany({
  where: { environment: 'sandbox', state: { in: ['UNKNOWN', 'SENDING'] },
    transferId: null, updatedAt: { lt: new Date(Date.now() - 120000) } },
  orderBy: [{ updatedAt: 'asc' }, { withdrawalId: 'asc' }], take: 3,
});
for (const payout of unconfirmed) {
  try { await this.recoverUnconfirmed(payout.withdrawalId); }
  catch { this.logger.warn('Asaas unconfirmed request could not be reconciled; funds retained.'); }
  finally {
    await this.db.asaasPayout.updateMany({
      where: { withdrawalId: payout.withdrawalId, transferId: null,
        state: { in: ['UNKNOWN', 'SENDING'] } },
      data: { updatedAt: new Date() },
    });
  }
}

