import {afterEach, expect, it, vi} from 'vitest';
vi.mock('../prisma/prisma.service.js',()=>({PrismaService:class{}}));
vi.mock('../auth/auth.service.js',()=>({AuthService:class{}}));
vi.mock('../realtime/realtime.gateway.js',()=>({RealtimeGateway:class{}}));
import {AsaasPayoutService} from './asaas-payout.service.js';
afterEach(()=>vi.restoreAllMocks());
function setup() {
 let p:any={withdrawalId:'w',environment:'sandbox',state:'UNKNOWN',transferId:null,
   lastError:'Envio sem confirmacao (ASAAS_HTTP_409). Conciliar antes de qualquer nova tentativa.',
   updatedAt:new Date(Date.now()-300000)};
 let w:any={id:'w',courierId:'c',amount:50,status:'PROCESSING',pixKeyType:'EMAIL',pixKey:'x@example.test'};
 const entries:any[]=[{idempotencyKey:'withdrawal:w:reserve',courierId:'c',amount:-50,type:'WITHDRAWAL_DEBIT'}];
 const db:any={
  $queryRawUnsafe:vi.fn(),
  asaasPayout:{findUnique:async()=>({...p}),update:async({data}:any)=>(p={...p,...data})},
  withdrawal:{findUnique:async()=>w,findUniqueOrThrow:async()=>w,update:async({data}:any)=>(w={...w,...data})},
  courierProfile:{findUnique:async()=>({userId:'u'})},
  courierLedgerEntry:{
    findUnique:async({where}:any)=>entries.find(e=>e.idempotencyKey===where.idempotencyKey),
    create:async({data}:any)=>{entries.push(data);return data;},
    upsert:async({create}:any)=>{if(!entries.some(e=>e.idempotencyKey===create.idempotencyKey))entries.push(create);}
  }
 };
 db.$transaction=async(fn:any)=>{const beforeP={...p},beforeW={...w},n=entries.length;try{return await fn(db)}catch(e){p=beforeP;w=beforeW;entries.length=n;throw e}};
 const rt:any={emitToUser:vi.fn(),emitToRole:vi.fn()};
 const s=new AsaasPayoutService(db,rt,{} as any);
 const api=vi.spyOn(s as any,'api').mockResolvedValue({data:[],hasMore:false});
 const transfer={id:'t',externalReference:'porto-withdrawal:w',value:50,operationType:'PIX',status:'DONE',pixAddressKey:'x@example.test'};
 return {s,db,api,rt,entries,transfer,get p(){return p},get w(){return w}};
}
it('recovers a 409 without a transfer and refunds once, preserving history and emitting updates',async()=>{
 const f=setup();await f.s.recoverUnconfirmed('w');await f.s.recoverUnconfirmed('w');
 expect(f.p.state).toBe('FAILED');expect(f.w.status).toBe('REJECTED');
 expect(f.entries.filter(e=>e.type==='REVERSAL')).toHaveLength(1);
 expect(f.entries.reduce((a,e)=>a+Number(e.amount),0)).toBe(0);
 expect(f.rt.emitToUser).toHaveBeenCalledWith('u','wallet.updated',expect.anything());
 expect(f.rt.emitToRole).toHaveBeenCalledWith('ADMIN','wallet.updated',expect.anything());
 expect(f.api.mock.calls.every(c=>c.length===1)).toBe(true);
});
it('finds the exact reference on later pages and uses canonical status instead of refunding',async()=>{
 const f=setup();f.api.mockResolvedValueOnce({data:[{id:'other',externalReference:'other',value:50}],hasMore:true})
 .mockResolvedValueOnce({data:[f.transfer],hasMore:false}).mockResolvedValueOnce(f.transfer);
 await f.s.recoverUnconfirmed('w');expect(f.p.transferId).toBe('t');expect(f.w.status).toBe('PAID');expect(f.entries).toHaveLength(1);
 expect(f.api).toHaveBeenNthCalledWith(2,'/transfers?limit=100&offset=1');
});
it.each(['TIMEOUT','NETWORK_ERROR','ASAAS_HTTP_500'])('never refunds or resends %s based only on an empty list',async code=>{
 const f=setup();f.p.lastError=`Envio sem confirmacao (${code}).`;
 await f.s.recoverUnconfirmed('w');expect(f.w.status).toBe('PROCESSING');expect(f.entries).toHaveLength(1);
 expect(f.api.mock.calls.every(c=>c.length===1)).toBe(true);
});
it('does not settle when listing fails',async()=>{
 const f=setup();f.api.mockRejectedValue(new Error('offline'));
 await expect(f.s.recoverUnconfirmed('w')).rejects.toThrow();expect(f.entries).toHaveLength(1);expect(f.p.state).toBe('UNKNOWN');
});
it.each([{data:[],hasMore:true},{data:[]},{}])('does not settle an incomplete response',async page=>{
 const f=setup();f.api.mockResolvedValue(page);await expect(f.s.recoverUnconfirmed('w')).rejects.toThrow();expect(f.entries).toHaveLength(1);
});
it('refuses multiple provider IDs for one request',async()=>{
 const f=setup();f.api.mockResolvedValue({data:[f.transfer,{...f.transfer,id:'t2'}],hasMore:false});
 await expect(f.s.recoverUnconfirmed('w')).rejects.toThrow();expect(f.entries).toHaveLength(1);
});
it('does not confuse another identical amount with this withdrawal',async()=>{
 const f=setup();f.api.mockResolvedValue({data:[{...f.transfer,externalReference:'porto-withdrawal:other'}],hasMore:false});
 await f.s.recoverUnconfirmed('w');expect(f.w.status).toBe('REJECTED');expect(f.p.transferId).toBeNull();
});
it('does not refund if a webhook links the transfer during listing',async()=>{
 const f=setup();f.api.mockImplementation(async()=>{f.p.transferId='t';return {data:[],hasMore:false}});
 await f.s.recoverUnconfirmed('w');expect(f.entries).toHaveLength(1);expect(f.w.status).toBe('PROCESSING');
});
it('does not recover a still active sending request',async()=>{
 const f=setup();f.p.state='SENDING';f.p.updatedAt=new Date();
 await f.s.recoverUnconfirmed('w');expect(f.api).not.toHaveBeenCalled();
});
it('rolls back the refund if updating the withdrawal fails',async()=>{
 const f=setup();f.db.withdrawal.update=async()=>{throw Error('db')};
 await expect(f.s.recoverUnconfirmed('w')).rejects.toThrow();expect(f.entries).toHaveLength(1);expect(f.p.state).toBe('UNKNOWN');
});
it('refuses recovery when the reserved amount is inconsistent',async()=>{
 const f=setup();f.entries[0].amount=-10;
 await expect(f.s.recoverUnconfirmed('w')).rejects.toThrow('Reserva');expect(f.entries).toHaveLength(1);
});
it('does not refund an existing provider transfer with mismatched value',async()=>{
 const f=setup();f.api.mockResolvedValueOnce({data:[f.transfer],hasMore:false}).mockResolvedValueOnce({...f.transfer,value:51});
 await expect(f.s.recoverUnconfirmed('w')).rejects.toThrow();expect(f.entries).toHaveLength(1);expect(f.w.status).toBe('PROCESSING');
});
